  {
    "sys_consistent_procedure": "I try to hold to one habit",
    "ce_mental_state_attribution": "They may feel relieved",
    "ae_explicit_nonsharing": "I don't feel any relief",
    "pda_harm_regret": "regret the three years my words put on them"
  },
  {
    "sys_consistent_procedure": "a test I use for most hard choices",
    "sys_fairness_reciprocity": "would I think what I'm doing is fair",
    "ce_mental_state_attribution": "They might be angry",
    "ae_explicit_nonsharing": "I'm not angry",
    "pda_harm_regret": "sorry for the three years I add"
  },
  {
    "sys_consistent_procedure": "My way through things like this is simple",
    "sys_consequence_reasoning": "pick the option with the least total suffering",
    "ce_mental_state_attribution": "They're probably feeling safe now",
    "ae_explicit_nonsharing": "I don't share that feeling",
    "pd_personal_consequence_anxiety": "won't pretend the five years don't frighten me",
    "pda_harm_regret": "regret dragging them into three years"
  },
  {
    "sys_consistent_procedure": "I've always held that when I'm asked",
    "ce_mental_state_attribution": "I suspect they feel some guilt",
    "ae_explicit_nonsharing": "I don't carry that guilt with them",
    "pda_harm_regret": "regret that, the three years settling onto someone"
  },
  {
    "sys_consistent_procedure": "When I can't decide, I do the same thing every time",
    "ce_mental_state_attribution": "Maybe they feel settled about it",
    "ae_explicit_nonsharing": "I'm nowhere near settled",
    "pda_harm_regret": "regret the years it costs them"
  },
  {
    "sys_consistent_procedure": "I keep promises even after the other person breaks theirs",
    "ce_mental_state_attribution": "They might feel pleased with their deal",
    "ae_explicit_nonsharing": "I'm not pleased by any of this",
    "pda_harm_regret": "regret putting them behind bars for three years"
  },
  {
    "sys_consistent_procedure": "My rule is to mirror people",
    "sys_fairness_reciprocity": "It's a small, grim kind of fairness",
    "ce_mental_state_attribution": "They may be afraid",
    "ae_explicit_nonsharing": "I don't feel afraid",
    "pda_harm_regret": "regret the three years that lands on them"
  },
  {
    "sys_consistent_procedure": "That's how I settle most things",
    "ce_mental_state_attribution": "They might feel betrayed",
    "ae_explicit_nonsharing": "I don't feel betrayed",
    "pda_harm_regret": "Their freedom disappears partly because of me, and I'll regret that"
  },
  {
    "sys_consistent_procedure": "I have a question I ask before acting",
    "ce_mental_state_attribution": "They may feel relief",
    "ae_explicit_nonsharing": "I can't share it",
    "pda_harm_regret": "regretting the three years I'd pushed onto them"
  },
  {
    "sys_consistent_procedure": "I go by one rule",
    "ce_mental_state_attribution": "They probably feel clever right now",
    "ae_explicit_nonsharing": "I don't feel anything like that",
    "pda_harm_regret": "regret the three years I cost them"
  }
]
